"""Run the complete original HTML script in NodeVM; no browser/provider calls."""
import json
import shutil
import subprocess
from pathlib import Path

import pytest

HARNESS = r'''
const fs=require('fs'),vm=require('vm'),assert=require('assert');
const mode=process.argv[1],id=n=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0'),sha=c=>c.repeat(64);let seq=50;
class Element{
constructor(tag='div'){this.tagName=tag;this.children=[];const named={};this.elements=new Proxy([],{get:(a,k)=>k in a?a[k]:(named[k]??=new Element('input'))});this.dataset={};this.textContent='';this.value='';this.hidden=true;this.disabled=false;this.checked=false;this.style={};this.listeners={};}
append(...x){this.children.push(...x)}replaceChildren(...x){this.children=x;this.textContent=''}prepend(...x){this.children.unshift(...x)}reset(){}addEventListener(n,f){(this.listeners[n]??=[]).push(f)}setAttribute(){}removeAttribute(n){delete this[n]}closest(){return null}querySelectorAll(){return []}scrollIntoView(){}focus(){}select(){}remove(){}get firstElementChild(){return this.children[0]}get options(){return this.children.filter(x=>x.tagName==='option')}get selectedOptions(){return this.options.filter(x=>x.value===this.value)}
}
const actor=sha('a'), prep=id(1),caseId=id(2),run=id(3),candidateId=id(4),calls=[];
const anchors={preparation_id:prep,case_id:caseId,run_id:run,actor_ref:actor,preparation_revision:2,request_revision:1};
function view(){return {...anchors,scope:'SYNTHETIC_REGISTERED_CASE_ADAPTER_PLAN',role:'enterprise_operator',plan_id:null,revision:0,state:'NOT_ADOPTED',can_adopt:true,read_only:false,steps:[],history:[],events:[],current_preview:{source_sha256:sha('b'),preparation_revision:2,required_goals:['LOCAL_MATERIAL_PREPARATION'],steps:[],goal_coverage:[]}}}
function catalog(){const value={...anchors,scope:'SYNTHETIC_SERVICE_CAPABILITY_SELECTION_PREVIEW',profile:'TRUSTED_SERVICE_SELECTION_V4',read_only:true,automatically_replayed:false,source_sha256:sha('c'),capability_catalog_sha256:sha('d'),selection_oracle:{state:mode==='unknown_catalog'?'UNKNOWN':mode==='multiple'?'MULTIPLE':'UNIQUE',minimal_solutions:[[]],selection_variant_count:mode==='multiple'?2:1,distinct_execution_graphs:1},catalog_snapshot:{releases:[{service_id:'synthetic-material-preparation',release_id:id(5),revision:1,release_sha256:sha('e')}],instances:[{instance_id:mode==='invalid_instance_id'?'bad instance':mode==='overlong_instance_id'?'x'.repeat(101):'park-b-synthetic-material-preparation-full-chain-instance',release_id:id(5),release_sha256:sha('e'),park_id:'park-b',roles:{enterprise_operator:'fixture-c'},resources:{},fields:{need_summary:{slot:'need_summary',input_field:'park_b_need'}},config_revision:2,config_sha256:sha('f')}]}};if(mode==='selected_variant'){value.catalog_snapshot.releases.push({...value.catalog_snapshot.releases[0],release_id:id(15),release_sha256:sha('8'),service_id:'synthetic-local-record-recheck'});value.catalog_snapshot.instances.push({...value.catalog_snapshot.instances[0],instance_id:'unselected-variant-instance',release_id:id(15),release_sha256:sha('8'),config_sha256:sha('9'),fields:{need_summary:{slot:'need_summary',input_field:'DO_NOT_SELECT_UNRELATED_FIELD'}}});}if(mode==='duplicate_metadata')value.catalog_snapshot.instances.push({...value.catalog_snapshot.instances[0]});return value;}
function selection(){const i=catalog().catalog_snapshot.instances[0];return {schema_version:1,binding:{capability_catalog_sha256:sha('d')},selections:[{release_id:id(5),revision:1,release_sha256:sha('e'),instance_id:mode==='missing_selected_instance'?'missing-instance':i.instance_id,config_revision:2,config_sha256:mode==='bad_selected_ref'?sha('9'):sha('f')}]};}
function candidate(){return {...anchors,scope:'SYNTHETIC_SERVICE_SELECTION_CANDIDATE',profile:'TRUSTED_SERVICE_SELECTION_V4',validator_version:4,selection:selection(),candidate_id:candidateId,candidate_sha256:sha('1'),verification_sha256:sha('2'),current_source_sha256:sha('c'),capability_catalog_sha256:sha('d'),read_only:true,provider_enabled:false,execution_enabled:false,new_grants:false,case_goal_completed:false,required_goals:['LOCAL_MATERIAL_PREPARATION'],steps:[{id:'P1',depends_on:[],responsibility:'enterprise_operator',output:'SYNTHETIC local material'}],state:mode==='expired'?'EXPIRED':'VERIFIED_STRUCTURE_ONLY',can_adopt:mode!=='expired'}}

function trace(){const snap=catalog().catalog_snapshot;const x={...anchors,scope:'SYNTHETIC_ADOPTED_PLAN_SOURCE_TRACE',plan_id:id(8),plan_revision:1,adoption:{event_id:id(10),source_sha256:sha('3'),catalog_sha256:sha('4'),registry_sha256:sha('5')},candidate:{candidate_id:candidateId,candidate_sha256:sha('1'),verification_sha256:sha('2'),validator_version:mode==='legacy_trace'?3:4},required_goals:['LOCAL_MATERIAL_PREPARATION'],steps:[{adapter_id:'P1',step_id:id(11),depends_on:[],contract_sha256:sha('6'),responsibility:'enterprise_operator',output:'SYNTHETIC local material',acceptance:'CURRENT_LOCAL_CONFIRMATION'}],historical_adoption_only:true,read_only:true,execution_enabled:false,new_grants:false,case_goal_completed:false,trace_sha256:sha('7')};if(mode!=='legacy_trace'){x.service_selection={profile:'TRUSTED_SERVICE_SELECTION_V4',capability_catalog_sha256:sha('d'),selection:selection()};x.service_capabilities=snap.releases;x.park_instances=snap.instances;if(mode==='bad_trace_ref')x.park_instances[0].config_sha256=sha('9');}return x;}
function goals(){return {...anchors,scope:'SYNTHETIC_ADOPTED_LOCAL_GOAL_RESULTS_ONLY',plan_id:id(8),plan_revision:1,read_only:true,case_goal_completed:false,results:[],source_trace:trace()};}

let lost=true,recovery='COMMITTED',denied=false,delayResolve=null,delay=false,adoptLost=true;
async function fetchAPI(path,options={}){calls.push({path,options});const method=options.method||'GET';let body,status=200;
if(path.endsWith('/goal-results')){body=goals();}
else if(path.endsWith('/command-recovery')){body={status:'NO_REQUEST',read_only:true,automatically_replayed:false,actor_ref:actor,case_id:caseId,run_id:run,current:view()};if(options.headers?.['Idempotency-Key'])body={scope:'SYNTHETIC_REGISTERED_CASE_ADAPTER_PLAN',preparation_id:prep,case_id:caseId,run_id:run,actor_ref:actor,status:'NOT_OBSERVED',read_only:true,historical_only:true,automatically_replayed:false,case_goal_completed:false,current:{...view(),read_only:true},event:null};}
else if(path.endsWith('/service-case-plan')){body=view();if(method==='POST'){if(mode==='lost_adopt'&&adoptLost){adoptLost=false;throw Error('SYNTHETIC lost ADOPT reply')}const submitted=JSON.parse(options.body);body={...view(),plan_id:id(8),revision:1,command_receipt:{actor_ref:actor,request_key:options.headers['Idempotency-Key'],action:'ADOPT',step_id:null,expected_revision:0,previous_plan_id:null,revision:1,plan_id:id(8)}};}}
else if(path.endsWith('/service-capabilities')){if(mode==='disabled'||denied)status=403;body=mode==='disabled'?{detail:'isolated service capability selection disabled'}:catalog();}
else if(path.endsWith('/service-selections/recovery')){status=denied?403:200;const key=options.headers['Idempotency-Key'];body={...anchors,scope:'SYNTHETIC_SERVICE_SELECTION_CANDIDATE',profile:'TRUSTED_SERVICE_SELECTION_V4',status:recovery,request_key:key,automatically_replayed:false,read_only:true,provider_enabled:false,execution_enabled:false,new_grants:false,case_goal_completed:false,items:recovery==='COMMITTED'?[candidate()]:[],attempts:[]};if(['PENDING','OUTCOME_UNKNOWN','FAILED_SAFE'].includes(recovery))body.attempts=[{attempt_id:id(9),status:recovery,outcome:recovery==='PENDING'?null:recovery==='FAILED_SAFE'?(mode==='selection_safe'||mode==='selection_safe_extra'?'INVALID_SERVICE_SELECTION':mode==='selection_bad_safe'?'UNREVIEWED_SERVICE_SELECTION':'INVALID_PLANNER_PROPOSAL'):mode==='bad_attempt'?'VALIDATED':'TIMEOUT_OUTCOME_UNKNOWN',validity:{version:2,seconds:900,created_at:'2026-10-14T01:00:00+00:00',expires_at:'2026-10-14T01:15:00+00:00'},automatically_replayed:false,read_only:true,can_adopt:false,provider_enabled:false,execution_enabled:false,new_grants:false}];if(mode==='selection_safe_extra')body.attempts[0].extra='not allowed';if(mode==='bad_recovery')body.actor_ref=sha('9');}
else if(path.endsWith('/preview')){if(denied)status=403;body=candidate();if(mode==='bad_source')body.current_source_sha256=sha('9');if(delay){delay=false;await new Promise(r=>delayResolve=r);}}
else if(path.endsWith('/service-selections')){body={};if(mode==='lost_generate'&&lost){lost=false;throw Error('SYNTHETIC lost selection reply')}}
else throw Error('unexpected path '+path);
return {ok:status===200,status,json:async()=>body};}
function page(seed={}){const elements=new Map(),get=id=>{if(!elements.has(id)){const e=new Element();e.id=id;elements.set(id,e)}return elements.get(id)},store={...seed};const storage=new Proxy({getItem:n=>store[n]??null,setItem:(n,v)=>store[n]=v,removeItem:n=>delete store[n]},{ownKeys:()=>Object.keys(store),getOwnPropertyDescriptor:()=>({enumerable:true,configurable:true})});get('run-access-valid-until').parentElement={firstChild:{textContent:''}};
const ctx=vm.createContext({console,Date,JSON,Map,Set,WeakMap,Number,String,Error,encodeURIComponent,URLSearchParams,structuredClone,TextEncoder,Option:function(t,v){const x=new Element('option');x.textContent=t;x.value=v;return x},crypto:{randomUUID:()=>id(seq++)},localStorage:storage,setTimeout:()=>1,clearTimeout:()=>{},location:{search:''},document:{getElementById:get,createElement:t=>new Element(t),querySelectorAll:()=>[],body:new Element('body'),addEventListener(){}},window:{addEventListener(){}},fetch:fetchAPI});
vm.runInContext(fs.readFileSync('src/parkweave/web.html','utf8').match(/<script[^>]*>([\s\S]*?)<\/script>/)[1],ctx);return {get,read:s=>vm.runInContext(s,ctx),snapshot:()=>({...store})};}
const posts=()=>calls.filter(c=>c.options.method==='POST');
(async()=>{let p=page();p.get('token').value='SYNTHETIC_UI_SESSION';await p.read('loadServiceCasePlan('+JSON.stringify(prep)+')');await p.get('service-selection-read').onclick();
if(mode==='disabled'){assert(p.get('service-selection-panel').hidden);assert(p.read('servicePlanView')!==null);assert.equal(posts().length,0);}
else if(['invalid_instance_id','overlong_instance_id'].includes(mode)){assert.equal(p.read('serviceSelectionCatalog'),null);assert.equal(posts().length,0);}
else if(mode==='unknown_catalog'){assert(p.get('service-selection-generate').disabled);await p.get('service-selection-generate').onclick();assert.equal(posts().length,0);}
else if(mode==='multiple'){assert(p.get('service-selection-status').textContent.includes('不同执行图数量 1'));assert.equal(posts().length,0);}
else if(mode==='stale'||mode==='late_exit'){delay=true;const pending=p.read('previewServiceSelection('+JSON.stringify(candidateId)+')');while(!delayResolve)await new Promise(r=>setImmediate(r));if(mode==='late_exit')p.read('clearServiceCasePlan()');else p.get('token').value='SYNTHETIC_other';delayResolve();await pending.catch(()=>{});assert.equal(p.read('serviceSelectionView'),null);}
else{if(mode==='pending')recovery='PENDING';if(mode==='outcome_unknown'||mode==='bad_attempt')recovery='OUTCOME_UNKNOWN';if(['failed_safe','selection_safe','selection_bad_safe','selection_safe_extra'].includes(mode))recovery='FAILED_SAFE';await p.get('service-selection-generate').onclick();assert.equal(posts().length,1);const generated=posts()[0];assert.deepEqual(Object.keys(JSON.parse(generated.options.body)).sort(),['expected_capability_catalog_sha256','expected_preparation_revision','expected_source_sha256']);assert.equal(JSON.parse(generated.options.body).expected_source_sha256,sha('c'));
if(['pending','outcome_unknown','bad_attempt','selection_bad_safe','selection_safe_extra'].includes(mode)){assert.equal(p.read('serviceSelectionView'),null);const snapshot=p.snapshot();assert(Object.keys(snapshot).some(n=>n.startsWith('parkweave.service-selection-original-key')));const n=posts().length;await p.get('service-selection-recover').onclick();assert.equal(posts().length,n);assert.deepEqual(p.snapshot(),snapshot);}
else if(mode==='failed_safe'||mode==='selection_safe'){assert.equal(p.read('serviceSelectionView'),null);assert.equal(Object.keys(p.snapshot()).length,0);assert.equal(posts().length,1);if(mode==='selection_safe'){const attempt={attempt_id:id(9),status:'FAILED_SAFE',outcome:'INVALID_SERVICE_SELECTION',validity:{version:2,seconds:900,created_at:'2026-10-14T01:00:00+00:00',expires_at:'2026-10-14T01:15:00+00:00'},automatically_replayed:false,read_only:true,can_adopt:false,provider_enabled:false,execution_enabled:false,new_grants:false};assert.equal(p.read('planCandidateAttemptValid('+JSON.stringify(attempt)+',"FAILED_SAFE")'),false);assert.equal(p.read('serviceSelectionAttemptValid('+JSON.stringify(attempt)+',"FAILED_SAFE")'),true);}}
else if(mode==='lost_generate'){const snapshot=p.snapshot(),name=Object.keys(snapshot).find(n=>n.startsWith('parkweave.service-selection-original-key'));assert(name);const handle=JSON.parse(snapshot[name]);assert.deepEqual(Object.keys(handle).sort(),['actor','case','id','key','run','v']);assert(!JSON.stringify(snapshot).includes('SYNTHETIC_UI_SESSION'));p=page(snapshot);p.get('token').value='SYNTHETIC_UI_SESSION';await p.read('loadServiceCasePlan('+JSON.stringify(prep)+')');await p.get('service-selection-read').onclick();await p.get('service-selection-recover').onclick();assert.equal(posts().length,1);assert.equal(calls.filter(c=>c.path.endsWith('/service-selections/recovery')).at(-1).options.headers['Idempotency-Key'],handle.key);}
else if(['bad_recovery','bad_source','bad_selected_ref','missing_selected_instance','duplicate_metadata'].includes(mode)){assert.equal(p.read('serviceSelectionView'),null);assert(Object.keys(p.snapshot()).some(n=>n.startsWith('parkweave.service-selection-original-key')));assert.equal(posts().length,1);}
else if(mode==='privacy'){denied=true;await p.read('previewServiceSelection('+JSON.stringify(candidateId)+')').catch(e=>p.read('servicePlanError(Object.assign(Error("revoked"),{status:403}))'));assert.equal(p.read('servicePlanView'),null);assert.equal(p.read('serviceSelectionView'),null);assert.equal(p.get('service-selection-result').children.length,0);}
else if(mode==='unknown_recovery'){/* preserve opaque handle while waiting for a late original request */p=page();p.get('token').value='SYNTHETIC_UI_SESSION';await p.read('loadServiceCasePlan('+JSON.stringify(prep)+')');await p.get('service-selection-read').onclick();lost=true;recovery='NOT_OBSERVED';await p.get('service-selection-generate').onclick();const n=posts().length;await p.get('service-selection-recover').onclick();await p.get('service-selection-generate').onclick().catch(()=>{});assert.equal(posts().length,n);assert(Object.keys(p.snapshot()).some(n=>n.startsWith('parkweave.service-selection-original-key')));}
else{assert.equal(p.read('serviceSelectionView.candidate_id'),candidateId);assert(p.get('service-selection-result').children.some(e=>e.textContent.includes('实际选中服务 synthetic-material-preparation')));assert(p.get('service-selection-result').children.some(e=>e.textContent.includes('park-b-synthetic-material-preparation-full-chain-instance')));assert(p.get('service-selection-result').children.some(e=>e.textContent.includes('park_b_need')));if(mode==='selected_variant'){const selected=p.get('service-selection-result').children.map(e=>e.textContent).join(' ');assert(!selected.includes('DO_NOT_SELECT_UNRELATED_FIELD'));assert(!selected.includes('unselected-variant-instance'));assert(!selected.includes('synthetic-local-record-recheck'));}p.get('service-plan-reason').value='SYNTHETIC explicit selection';const before=posts().length;await p.get('service-plan-adopt').onclick();assert.equal(posts().length,before);p.get('service-selection-confirm').checked=true;await p.get('service-plan-adopt').onclick();if(mode==='expired'){assert.equal(posts().length,before);}else{assert.equal(posts().length,before+1);const body=JSON.parse(posts().at(-1).options.body);assert.equal(body.candidate_id,candidateId);assert.equal(body.expected_source_sha256,sha('c'));assert.equal(body.expected_verification_sha256,sha('2'));if(mode==='lost_adopt'){assert(p.read('servicePlanRecoveryHandle')!==null);const n=posts().length;await p.get('service-plan-retry').onclick();assert.equal(posts().length,n);}else{assert.equal(p.read('servicePlanView.plan_id'),id(8));if(['trace','legacy_trace','bad_trace_ref'].includes(mode)){await p.get('goal-results-read').onclick();const original=JSON.stringify(p.read('goalResultView.source_trace'));await p.get('goal-results-source-read').onclick();assert.equal(JSON.stringify(p.read('goalResultView.source_trace')),original);if(mode==='bad_trace_ref'){assert.equal(p.get('goal-results-source').children.length,0);}else{const text=p.get('goal-results-source').children.map(e=>e.textContent).join('\n');assert([sha('1'),sha('2'),sha('3'),sha('4'),sha('5'),sha('6')].every(hash=>text.includes(hash)));assert.equal(p.read('goalResultView.source_trace.trace_sha256'),sha('7'));if(mode==='trace'){assert(text.includes('实际选中服务 synthetic-material-preparation'));assert(text.includes('park_b_need'));assert(text.includes(sha('d')));}else assert(!text.includes('原冻结服务选择目录'));}}}}}
}
console.log(JSON.stringify({result:'PASS',mode,http:calls.length,posts:posts().length,completeOriginalHTML:true}));})().catch(e=>{console.error(e.stack);process.exitCode=1});
'''


@pytest.mark.parametrize("mode", ["disabled", "unknown_catalog", "multiple", "stale", "happy", "expired", "lost_generate", "bad_recovery", "bad_source", "privacy", "unknown_recovery", "lost_adopt", "pending", "outcome_unknown", "bad_attempt", "failed_safe", "late_exit", "non_uuid_instance", "invalid_instance_id", "overlong_instance_id", "selection_safe", "selection_bad_safe", "selection_safe_extra", "bad_selected_ref", "trace", "legacy_trace", "bad_trace_ref", "selected_variant", "missing_selected_instance", "duplicate_metadata"])
def test_service_selection_complete_html_nodevm(mode):
    assert shutil.which("node"), "Node is required for complete original HTML verification"
    root = Path(__file__).resolve().parents[1]
    completed = subprocess.run(["node", "-e", HARNESS, mode], cwd=root, text=True, capture_output=True, timeout=25)
    assert completed.returncode == 0, completed.stdout + completed.stderr
    result = json.loads(completed.stdout.strip().splitlines()[-1])
    assert result["result"] == "PASS" and result["completeOriginalHTML"] is True
